import { test } from "node:test";
import assert from "node:assert/strict";
import { displayName } from "../../src/users/index.ts";

test("display name falls back to the email", () => {
  assert.equal(displayName({ id: "u2", email: "grace@example.com" }), "grace@example.com");
  assert.equal(displayName({ id: "u3", name: "  ", email: "lin@example.com" }), "lin@example.com");
});
